// Oeste LogoCell — Huntington theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with arbitrary values, JSX transform.
// Requires Huntington tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/huntington/src/index.js
// Docs: https://oeste.hiddeninwest.com/huntington/#/components/logo-cell

export function LogoCell({ logo, alt }) {
  return (
    <div className="flex w-[160px] items-center justify-center rounded-[14px] border border-[var(--color-border)] bg-[var(--color-card)] px-6 py-10">
      <span className="flex w-[70%] max-h-[60px] items-center justify-center" role={alt ? "img" : undefined} aria-label={alt}>{logo}</span>
    </div>
  );
}
